function kuaiz_cms_install_normalized_source(string $source): string
{
    $placeholders = [
        'RELEASE_VERSION' => 'RELEASE_VERSION',
        'INSTALL_TOKEN_SHA256' => 'INSTALL_TOKEN_SHA256',
        'PAYLOAD_SHA256' => 'PAYLOAD_SHA256',
        'PAYLOAD_BASE64' => 'PAYLOAD_JSON_BASE64',
        'RELEASE_SIGNATURE_TOKEN' => 'RELEASE_SIGNATURE_TOKEN',
        'RELEASE_PUBLIC_KEY_BASE64' => 'RELEASE_PUBLIC_KEY_BASE64',
        'RELEASE_PUBLIC_KEY_FINGERPRINT' => 'RELEASE_PUBLIC_KEY_FINGERPRINT',
    ];
    foreach ($placeholders as $constant => $placeholderName) {
        $pattern = '/^const KUAIZ_CMS_' . preg_quote($constant, '/') . " = '[^'\\r\\n]*';$/m";
        $placeholder = '__' . 'KUAIZ_' . $placeholderName . '__';
        $replacement = "const KUAIZ_CMS_{$constant} = '{$placeholder}';";
        $source = preg_replace($pattern, $replacement, $source, 1, $count);
        if (!is_string($source) || $count !== 1) {
            kuaiz_cms_install_fail('安装器逻辑已被修改，请重新下载。', 'installer_template_modified');
        }
    }
    return $source;
}

